using System.Text.Json;
using LexiSharp.Ranking;
using Xunit;

namespace LexiSharp.Tests;

/// <summary>
/// Differential tests for the retrieval metrics against <c>ir_measures</c>.
/// </summary>
/// <remarks>
/// The fixture is generated by <c>scripts/generate-retrieval-metrics-fixture.py</c> and checked in,
/// so the test suite does not need Python or <c>ir_measures</c> installed. The generator pins its
/// seed and the <c>ir_measures</c> version in the file. Duplicate retrieved ids are deliberately
/// absent from the generated cases: this library deduplicates, while the reference does not, and
/// that convention is asserted separately below.
/// </remarks>
public class RetrievalMetricsDifferentialTests
{
    private sealed class Fixture
    {
        public string Source { get; init; } = string.Empty;

        public string Version { get; init; } = string.Empty;

        public int Seed { get; init; }

        public List<Case> Cases { get; init; } = [];
    }

    private sealed class Case
    {
        public string Name { get; init; } = string.Empty;

        public int K { get; init; }

        public Dictionary<string, double> Qrels { get; init; } = [];

        public string[] Retrieved { get; init; } = [];

        public Expected Expected { get; init; } = new();
    }

    private sealed class Expected
    {
        public double NdcgLinear { get; init; }

        public double NdcgExponential { get; init; }

        public double Ap { get; init; }

        public double Rr { get; init; }

        public double Recall { get; init; }

        public double Precision { get; init; }
    }

    [Fact]
    public void Metrics_MatchIrMeasures()
    {
        string path = Path.Combine(
            AppContext.BaseDirectory, "TestData", "retrieval-metrics-ir-measures.json");

        Fixture fixture = JsonSerializer.Deserialize<Fixture>(
            File.ReadAllText(path),
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })
            ?? throw new InvalidOperationException("The retrieval-metrics fixture is empty.");

        Assert.Equal("ir_measures", fixture.Source);
        Assert.NotEmpty(fixture.Version);
        Assert.NotEmpty(fixture.Cases);

        foreach (Case test in fixture.Cases)
        {
            string[] relevant = test.Qrels
                .Where(pair => pair.Value > 0)
                .Select(pair => pair.Key)
                .ToArray();

            AssertClose(
                test.Expected.NdcgLinear,
                RetrievalMetrics.NdcgAtK(test.Retrieved, test.Qrels, test.K, NdcgGain.Linear),
                test.Name,
                "nDCG linear");

            AssertClose(
                test.Expected.NdcgExponential,
                RetrievalMetrics.NdcgAtK(test.Retrieved, test.Qrels, test.K, NdcgGain.Exponential),
                test.Name,
                "nDCG exponential");

            AssertClose(
                test.Expected.Ap,
                RetrievalMetrics.AveragePrecisionAtK(test.Retrieved, relevant, test.K),
                test.Name,
                "AP");

            AssertClose(
                test.Expected.Rr,
                RetrievalMetrics.ReciprocalRankAtK(test.Retrieved, relevant, test.K),
                test.Name,
                "RR");

            AssertClose(
                test.Expected.Recall,
                RetrievalMetrics.RecallAtK(test.Retrieved, relevant, test.K),
                test.Name,
                "Recall");

            AssertClose(
                test.Expected.Precision,
                RetrievalMetrics.PrecisionAtK(test.Retrieved, relevant, test.K),
                test.Name,
                "Precision");
        }
    }

    [Fact]
    public void EmptyRelevantSet_ScoresZeroEverywhere()
    {
        string[] retrieved = ["a", "b"];

        Assert.Equal(0, RetrievalMetrics.NdcgAtK(retrieved, Array.Empty<string>(), 10), 12);
        Assert.Equal(0, RetrievalMetrics.AveragePrecisionAtK(retrieved, Array.Empty<string>(), 10), 12);
        Assert.Equal(0, RetrievalMetrics.ReciprocalRankAtK(retrieved, Array.Empty<string>(), 10), 12);
        Assert.Equal(0, RetrievalMetrics.RecallAtK(retrieved, Array.Empty<string>(), 10), 12);
        Assert.Equal(0, RetrievalMetrics.PrecisionAtK(retrieved, Array.Empty<string>(), 10), 12);
    }

    [Fact]
    public void DuplicateRetrievedIds_CountOnce()
    {
        string[] retrieved = ["a", "a", "b"];
        string[] relevant = ["a", "b"];

        Assert.Equal(1, RetrievalMetrics.NdcgAtK(retrieved, relevant, 3), 12);
        Assert.Equal(1, RetrievalMetrics.RecallAtK(retrieved, relevant, 3), 12);
        Assert.Equal(2.0 / 3, RetrievalMetrics.PrecisionAtK(retrieved, relevant, 3), 12);
        Assert.Equal(1, RetrievalMetrics.AveragePrecisionAtK(retrieved, relevant, 3), 12);
    }

    private static void AssertClose(double expected, double actual, string caseName, string metric)
    {
        Assert.True(
            Math.Abs(expected - actual) <= 1e-9,
            $"{caseName}: {metric} expected {expected:R}, got {actual:R}");
    }
}
